INSERT INTO `attivita_eventi` VALUES (1,749,'Simulazione WebXR - Braccio robotico 3D','Laboratorio di robototecnica con simulazione tecnica WebXR del braccio robotico in 3D, pensato per utenti registrati del portale e per l\'orientamento tecnologico.','https://Novia-RDI-XR-Robotics.github.io/a-frame-xr-tutorial/','2026-10-20 10:00:00',30,1,'laboratorio',45,1,NULL,'pubblicata','2026-05-03 19:23:45','2026-09-16 20:10:06'),(2,7862,'Medical Holodeck - Tutorial VR e Setup Hardware','Laboratorio interattivo su Medical Holodeck. Scopri come attivare le license key su dispositivo standalone o PC, e come configurare l\'hardware VR per un setup PC-VR ottimale. Sessione teorica e pratica.','https://store.steampowered.com/app/754010/Medicalholodeck_Spatial_OS_obuchat_xirurgii_sozdavat_czifrovye_dvojniki_s_pomoshhyu_II_i_DICOM_i_izuchat_anatomiyu_cheloveka/','2026-10-21 14:00:00',25,1,'laboratorio',90,1,'https://medicalholodeck.com/en/hardware-setup/','pubblicata','2026-05-09 20:37:48','2026-09-11 19:49:44'),(3,7863,'test chirurgico','Attività di prova: test chirurgico associato a partner FSL Medpark.','simulazione_test_chirurgico.html','2026-10-22 23:45:06',20,1,'laboratorio',2,0,'https://www.youtube.com/watch?v=2TU5E-tzg0U&list=PLLleQABuPzNwAX3uENiZ2I0svWxdJH-Wp&index=4','pubblicata','2026-05-17 21:45:06','2026-09-13 14:36:32'),(4,7863,'test 3d','Attività dimostrativa 3D con il modello AttenuationTest.glb inserito nel repository Open House.','simulazione_test_3d.html','2026-10-23 13:58:54',25,0,'laboratorio',45,1,'mdeli%203d/AttenuationTest.glb','pubblicata','2026-07-10 11:58:54','2026-09-11 19:49:44'),(5,7864,'settore produzione','tuor virtuale realizzato nel settore della produzione','https://www.virtualtour-360.it/vt/graphiti-h1d2/vt-web/','2026-09-13 14:50:00',30,0,'tour_virtuale',60,1,'https://www.virtualtour-360.it/vt/graphiti-h1d2/vt-web/','pubblicata','2026-09-13 12:41:40','2026-09-13 12:44:44');
